file_editor: {"command": "create", "path": "/app/workspace/extract.py", "file_text": """"Extract date and total amount from receipt images and save to Excel.

Dates: look for DD/MM/YYYY or DD-MM-YYYY (also DD/MM/YY) patterns, validate.
Totals: use priority keyword matching with exclusion keywords.
"""
import os
import re
import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"

PRIORITY_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE",
     "NETT TOTAL", "NET TOTAL"],
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL", "TAX", "GST", "SST",
    "DISCOUNT", "CHANGE", "CASH TENDERED",
]

NUMBER_RE = re.compile(r"(?<![\d.])(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})(?!\d)")
DATE_RE = re.compile(r"(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2,4})")


def ocr_text(path):
    """Run OCR with multiple configurations and return a list of outputs."""
    img = Image.open(path)
    texts = []
    for psm in (6, 3, 4):
        try:
            t = pytesseract.image_to_string(img, config=f"--psm {psm}")
            if t.strip():
                texts.append(t)
        except Exception:
            pass
    return texts


def parse_date(day, month, year):
    d = int(day)
    m = int(month)
    y = int(year)
    if len(year) == 2:
        y = 2000 + y if y < 70 else 1900 + y
    if not (1 <= d <= 31 and 1 <= m <= 12 and 1900 <= y <= 2099):
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_date(texts):
    """Try to find a valid date in texts. Prefer dates near 'Date' keyword."""
    best = None
    best_near_keyword = False
    for text in texts:
        lines = text.splitlines()
        for i, line in enumerate(lines):
            for m in DATE_RE.finditer(line):
                day, month, year = m.groups()
                parsed = parse_date(day, month, year)
                if not parsed:
                    continue
                near_kw = "DATE" in line.upper() or "DATE" in (
                    lines[i - 1].upper() if i > 0 else ""
                )
                if near_kw and not best_near_keyword:
                    best = parsed
                    best_near_keyword = True
                elif best is None:
                    best = parsed
        if best_near_keyword:
            return best
    return best


def clean_num(s):
    """Convert '1,234.56' to '1234.56'."""
    return s.replace(",", "")


def line_has_exclusion(line_upper):
    for kw in EXCLUSION_KEYWORDS:
        if kw in line_upper:
            return True
    return False


def extract_total_from_text(text):
    """Return the extracted total string, or None."""
    lines = text.splitlines()
    n = len(lines)
    for kw_group in PRIORITY_KEYWORDS:
        for i, raw in enumerate(lines):
            line_upper = raw.upper()
            if not any(kw in line_upper for kw in kw_group):
                continue
            if line_has_exclusion(line_upper):
                continue
            nums = NUMBER_RE.findall(raw)
            if nums:
                return clean_num(nums[-1])
            if i + 1 < n:
                nxt = lines[i + 1]
                nums_next = NUMBER_RE.findall(nxt)
                if nums_next:
                    return clean_num(nums_next[-1])
    return None


def extract_total(texts):
    for text in texts:
        result = extract_total_from_text(text)
        if result is not None:
            return result
    return None


def format_total(val):
    if val is None:
        return None
    try:
        f = float(val)
    except ValueError:
        return None
    return f"{f:.2f}"


def main():
    names = sorted(
        n for n in os.listdir(IMG_DIR)
        if n.lower().endswith((".jpg", ".jpeg", ".png"))
    )

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    for name in names:
        path = os.path.join(IMG_DIR, name)
        texts = ocr_text(path)
        date = extract_date(texts)
        total = format_total(extract_total(texts))
        print(f"{name}: date={date}, total={total}")
        ws.append([name, date, total])

    wb.save(OUT_XLSX)
    print(f"Saved: {OUT_XLSX}")


if __name__ == "__main__":
    main()
